Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].
Ltac ldcellP F D a z H :=
  stepLD F D (word_to_le_bytes 4 (Z_to_bv 64 z)) (Z_to_bv 64 z)
    ltac:(rdn_addr a; repeat rdn_peel1; exact H) ltac:(apply bytes_le_to_Z_4; unorm; lia);
  rewrite ?(v_lw_small z) by lia.
Ltac fixv' v tac := lazymatch goal with |- msteps _ (mkst (regupd _ _ ?x) _ _ _) _ => first [ constr_eq x v | replace x with v by (symmetry; tac) ] end.
Ltac cur_regs := lazymatch goal with |- msteps _ (mkst ?R _ _ _) _ => R end.
(* [comment removed for export] *)
Ltac tabrd tab TB B R E :=
  lazymatch goal with |- msteps _ (mkst (regupd _ _ (v_add _ ?X)) _ _ _) _ =>
    let BX := fresh "BX" in
    pose proof (B _ : (0 <= bv_unsigned X <= 1020)%Z) as BX;
    rewrite (rbl_add_idx tab X) by lia;
    destruct (TB (bv_unsigned X) BX) as (R & E) end.
Ltac tabld F D R E :=
  lazymatch type of R with _ = Some ?bs => lazymatch type of E with _ = bv_unsigned ?v =>
    stepLD F D bs v ltac:(addr_norm; rewrite ?Z.add_0_r; exact R) ltac:(exact E) end end.

