    (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
    (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 19)))
    (Z_to_bv 64 (s - 48)) (word_to_le_bytes 8 (getr regs 20)).
(* [comment removed for export] *)
Definition MCP_A (m : word -> option byte) (s pc : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (FCP m s ret regs) (Z_to_bv 64 pc) (word_to_le_bytes 4 (Z_to_bv 64 0)).
(* [comment removed for export] *)
Definition DIMC (m : word -> option byte) (s : Z) (w h : Z) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 52)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 56)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 52)) (word_to_le_bytes 4 (Z_to_bv 64 w)))
    (Z_to_bv 64 (s - 56)) (word_to_le_bytes 4 (Z_to_bv 64 h)).

Section Count.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Section Segs.
  Variable rom : word -> option byte.

  Ltac pxo PX := repeat (apply PIXat_out; [| rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; lia | rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn; lia]); exact PX.

  (* [comment removed for export] *)
  Lemma cp_A : forall regs m (s pixs pc : Z) (v : pixv) (ret : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 64)%Z -> p_d v = 1%Z ->
    (s <= pc)%Z -> (pc + 4 < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true -> store_ok SEGS m (Z_to_bv 64 pc) 4 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> getr regs 11 = Z_to_bv 64 pc -> getr regs 12 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x78fb8 : word) m rom) (mkst regs' (0xfa23c : word) (MCP_A m s pc ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 1 = Z_to_bv 64 0x79010
      /\ getr regs' 10 = Z_to_bv 64 256 /\ getr regs' 11 = Z_to_bv 64 4
      /\ getr regs' 9 = Z_to_bv 64 pc /\ getr regs' 19 = Z_to_bv 64 pixs /\ getr regs' 8 = Z_to_bv 64 0
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 18; 19]%list) regs regs'.
Proof.
