  (* [comment removed for export] *)
  Lemma cp_An : forall regs m (s pc : Z) (ret : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (s <= pc)%Z -> (pc + 4 < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true -> store_ok SEGS m (Z_to_bv 64 pc) 4 = true ->
    rdn SEGS (MCP_A m s pc ret regs) (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) ->
    rdn SEGS (MCP_A m s pc ret regs) (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 0 -> getr regs 11 = Z_to_bv 64 pc ->
    exists regs',
      msteps SEGS (mkst regs (0x78fb8 : word) m rom) (mkst regs' (0x6304c : word) (MCP_A m s pc ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret
      /\ getr regs' 10 = Z_to_bv 64 0x1189d /\ getr regs' 11 = Z_to_bv 64 0x16282 /\ getr regs' 12 = Z_to_bv 64 1
      /\ getr regs' 8 = getr regs 8 /\ getr regs' 9 = getr regs 9 /\ getr regs' 18 = getr regs 18 /\ getr regs' 19 = getr regs 19
      /\ getr regs' 20 = getr regs 20
