  (* [comment removed for export] *)
  Lemma cp_T0 : forall regs m (tab : Z), (0 <= tab)%Z -> (tab + 1024 < 2 ^ 64)%Z -> getr regs 10 = Z_to_bv 64 tab ->
    exists regs',
      msteps SEGS (mkst regs (0x79010 : word) m rom) (mkst regs' (0x79020 : word) m rom)
      /\ getr regs' 18 = Z_to_bv 64 tab /\ getr regs' 12 = Z_to_bv 64 tab /\ getr regs' 11 = Z_to_bv 64 (tab + 1024)
