  Lemma cp_T : forall regs m (p : Z), (0 <= p)%Z -> (p + 4 < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 p) 4 = true -> getr regs 12 = Z_to_bv 64 p ->
    exists regs' (wv : word),
      msteps SEGS (mkst regs (0x79020 : word) m rom) (mkst regs' (0x79080 : word) (wbytes m (Z_to_bv 64 p) (word_to_le_bytes 4 wv)) rom)
      /\ getr regs' 12 = Z_to_bv 64 (p + 4)
      /\ regs_agree (fun r => In r [5; 6; 7; 10; 12; 13; 14; 15; 16; 17]%list) regs regs'.
Proof.
