  Lemma cp_B : forall regs m (s pixs : Z) (v : pixv),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 64)%Z ->
    (1 <= p_w v < 2 ^ 31)%Z -> (1 <= p_h v < 2 ^ 31)%Z -> (1 <= p_wpl v < 2 ^ 24)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 19 = Z_to_bv 64 pixs ->
    exists regs',
      msteps SEGS (mkst regs (0x79084 : word) m rom) (mkst regs' (0x790fc : word) (DIMC m s (p_w v) (p_h v)) rom)
      /\ getr regs' 12 = Z_to_bv 64 0 /\ getr regs' 13 = Z_to_bv 64 0 /\ getr regs' 11 = Z_to_bv 64 (p_h v)
      /\ getr regs' 16 = Z_to_bv 64 (p_w v / 32) /\ getr regs' 15 = Z_to_bv 64 (p_w v mod 32)
      /\ getr regs' 20 = Z_to_bv 64 (4 * p_wpl v) /\ getr regs' 5 = Z_to_bv 64 (4 * (p_w v / 32))
      /\ getr regs' 6 = Z_to_bv 64 (p_data v) /\ getr regs' 10 = Z_to_bv 64 (p_data v)
