  (* [comment removed for export] *)
  Lemma cp_Rw : forall regs m (i fw wpl data line : Z),
    (0 <= i < 2 ^ 31)%Z -> (1 <= fw < 2 ^ 26)%Z -> (1 <= wpl < 2 ^ 24)%Z -> (0 <= data)%Z ->
    getr regs 16 = Z_to_bv 64 fw -> getr regs 20 = Z_to_bv 64 (4 * wpl) -> getr regs 12 = Z_to_bv 64 i ->
    getr regs 5 = Z_to_bv 64 (4 * fw) -> getr regs 10 = Z_to_bv 64 data -> getr regs 6 = Z_to_bv 64 line ->
    exists regs',
      msteps SEGS (mkst regs (0x790fc : word) m rom) (mkst regs' (0x7911c : word) m rom)
      /\ getr regs' 7 = Z_to_bv 64 (data + (4 * fw + 4 * wpl * i)) /\ getr regs' 28 = Z_to_bv 64 line
      /\ regs_agree (fun r => In r [7; 28]%list) regs regs'.
