  (* [comment removed for export] *)
  Lemma cp_Wd : forall (b : bool) regs m (p tab : Z) (bs : list byte) (v : word) (tbs : Z -> list byte) (tvs : Z -> word),
    (0 <= p)%Z -> (p + 4 < 2 ^ 64)%Z -> (0 <= tab)%Z -> (tab + 1024 < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 p) 4 = Some bs -> bytes_le_to_Z bs = bv_unsigned v ->
    c_eq v (Z_to_bv 64 0) = b ->
    (forall o : Z, (0 <= o <= 1020)%Z -> rdn SEGS m (Z_to_bv 64 (tab + o)) 4 = Some (tbs o) /\ bytes_le_to_Z (tbs o) = bv_unsigned (tvs o)) ->
    getr regs 28 = Z_to_bv 64 p -> getr regs 18 = Z_to_bv 64 tab ->
    exists regs',
      msteps SEGS (mkst regs (0x7911c : word) m rom) (mkst regs' (0x79114 : word) m rom)
