  (* [comment removed for export] *)
  Lemma cp_Eb : forall (b : bool) regs m (line fw tab : Z) (bs : list byte) (v : word) (tbs : Z -> list byte) (tvs : Z -> word),
    (0 <= line)%Z -> (0 <= fw < 2 ^ 26)%Z -> (line + 4 * fw + 4 < 2 ^ 64)%Z -> (0 <= tab)%Z -> (tab + 1024 < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 (line + 4 * fw)) 4 = Some bs -> bytes_le_to_Z bs = bv_unsigned v ->
    c_eq (v_and (v_lw v) (getr regs 17)) (Z_to_bv 64 0) = b ->
    (forall o : Z, (0 <= o <= 1020)%Z -> rdn SEGS m (Z_to_bv 64 (tab + o)) 4 = Some (tbs o) /\ bytes_le_to_Z (tbs o) = bv_unsigned (tvs o)) ->
    getr regs 7 = Z_to_bv 64 fw -> getr regs 6 = Z_to_bv 64 line -> getr regs 18 = Z_to_bv 64 tab ->
    exists regs',
      msteps SEGS (mkst regs (0x7918c : word) m rom) (mkst regs' (0x790ec : word) m rom)
      /\ regs_agree (fun r => In r [7; 14; 28; 29; 30]%list) regs regs'.
Proof.
