  (* [comment removed for export] *)
  Lemma cp_Nn : forall regs m (i h wpl line : Z), (0 <= i)%Z -> (i + 1 < h)%Z -> (h < 2 ^ 31)%Z -> (0 <= line)%Z ->
    getr regs 13 = Z_to_bv 64 i -> getr regs 12 = Z_to_bv 64 i -> getr regs 11 = Z_to_bv 64 h ->
    getr regs 6 = Z_to_bv 64 line -> getr regs 20 = Z_to_bv 64 (4 * wpl) ->
    exists regs',
      msteps SEGS (mkst regs (0x790ec : word) m rom) (mkst regs' (0x790fc : word) m rom)
      /\ getr regs' 13 = Z_to_bv 64 (i + 1) /\ getr regs' 12 = Z_to_bv 64 (i + 1) /\ getr regs' 6 = Z_to_bv 64 (line + 4 * wpl)
      /\ regs_agree (fun r => In r [6; 12; 13]%list) regs regs'.
Proof.
