  (* [comment removed for export] *)
  Lemma cp_Nx : forall regs m (i pc tab : Z), (0 <= i)%Z -> (i + 1 < 2 ^ 31)%Z -> (0 <= pc)%Z -> (pc + 4 < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 pc) 4 = true ->
    getr regs 13 = Z_to_bv 64 i -> getr regs 11 = Z_to_bv 64 (i + 1) -> getr regs 9 = Z_to_bv 64 pc -> getr regs 8 = Z_to_bv 64 0 ->
    getr regs 18 = Z_to_bv 64 tab ->
    exists regs' (wv : word),
      msteps SEGS (mkst regs (0x790ec : word) m rom) (mkst regs' (0xfa374 : word) (wbytes m (Z_to_bv 64 pc) (word_to_le_bytes 4 wv)) rom)
      /\ getr regs' 1 = Z_to_bv 64 0x79280 /\ getr regs' 10 = Z_to_bv 64 tab
      /\ regs_agree (fun r => In r [1; 6; 10; 12; 13]%list) regs regs'.
Proof.
